"use client";

import { useLocalization } from "@jcoder-stack/abp-react/react";
import { ChevronRightIcon } from "lucide-react";
import { useId, useState } from "react";
import { cn } from "@/lib/utils";
import type { TreeNode } from "./tree-helpers";
import { TriStateCheckbox } from "./tri-state-checkbox";

export interface TreeProps {
  nodes: TreeNode[];
  defaultExpanded?: string[];
  checkable?: boolean;
  checked?: Set<string>;
  indeterminate?: Set<string>;
  onCheckChange?: (id: string, checked: boolean) => void;
}

const EMPTY_SET: Set<string> = new Set();

/**
 * 通用树形块：零业务知识，只负责层级渲染/展开收起/勾选态展示与上报。
 * 级联策略（勾子强制父链、去父清子树等）不在此处实现，由消费方基于 tree-helpers 的
 * 纯函数（collectSubtreeIds/findParentChain/deriveIndeterminate）自行组合。
 */
export function Tree({
  nodes,
  defaultExpanded,
  checkable = false,
  checked = EMPTY_SET,
  indeterminate = EMPTY_SET,
  onCheckChange,
}: TreeProps) {
  const [expandedIds, setExpandedIds] = useState<Set<string>>(() => new Set(defaultExpanded));

  function toggleExpanded(id: string) {
    setExpandedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  }

  return (
    <div data-slot="tree">
      {nodes.map((node) => (
        <TreeRow
          key={node.id}
          node={node}
          depth={0}
          expandedIds={expandedIds}
          onToggleExpanded={toggleExpanded}
          checkable={checkable}
          checked={checked}
          indeterminate={indeterminate}
          onCheckChange={onCheckChange}
        />
      ))}
    </div>
  );
}

function TreeRow({
  node,
  depth,
  expandedIds,
  onToggleExpanded,
  checkable,
  checked,
  indeterminate,
  onCheckChange,
}: {
  node: TreeNode;
  depth: number;
  expandedIds: Set<string>;
  onToggleExpanded: (id: string) => void;
  checkable: boolean;
  checked: Set<string>;
  indeterminate: Set<string>;
  onCheckChange?: (id: string, checked: boolean) => void;
}) {
  const L = useLocalization();
  const labelId = useId();
  const hasChildren = (node.children?.length ?? 0) > 0;
  const isExpanded = expandedIds.has(node.id);
  const icon = typeof node.icon === "function" ? node.icon({ expanded: isExpanded }) : node.icon;
  const checkedState = indeterminate.has(node.id) ? "indeterminate" : checked.has(node.id);

  return (
    <div data-slot="tree-node">
      <div
        className="flex items-center gap-1 py-1"
        style={{ paddingLeft: depth * 16 }}
        data-testid={`tree-row-${node.id}`}
      >
        {hasChildren ? (
          <button
            type="button"
            className="flex size-4 shrink-0 items-center justify-center text-muted-foreground"
            aria-expanded={isExpanded}
            aria-label={isExpanded ? L("Tree:Collapse") : L("Tree:Expand")}
            data-testid={`tree-toggle-${node.id}`}
            onClick={() => onToggleExpanded(node.id)}
          >
            <ChevronRightIcon
              className={cn("size-4 transition-transform", isExpanded && "rotate-90")}
            />
          </button>
        ) : (
          <span className="size-4 shrink-0" aria-hidden="true" />
        )}
        {icon !== undefined && icon !== null ? (
          <span className="flex shrink-0 items-center" data-testid={`tree-icon-${node.id}`}>
            {icon}
          </span>
        ) : null}
        {checkable ? (
          <TriStateCheckbox
            checked={checkedState}
            disabled={node.disabled}
            aria-labelledby={labelId}
            data-testid={`tree-checkbox-${node.id}`}
            onCheckedChange={(value: boolean | "indeterminate") =>
              onCheckChange?.(node.id, value === true)
            }
          />
        ) : null}
        <span id={labelId} className="text-sm">
          {node.label}
        </span>
      </div>
      {hasChildren && isExpanded ? (
        <div data-slot="tree-children">
          {node.children?.map((child) => (
            <TreeRow
              key={child.id}
              node={child}
              depth={depth + 1}
              expandedIds={expandedIds}
              onToggleExpanded={onToggleExpanded}
              checkable={checkable}
              checked={checked}
              indeterminate={indeterminate}
              onCheckChange={onCheckChange}
            />
          ))}
        </div>
      ) : null}
    </div>
  );
}

import { CheckIcon, MinusIcon } from "lucide-react";
import { Checkbox as CheckboxPrimitive } from "radix-ui";
import type * as React from "react";
import { cn } from "@/lib/utils";

/** 三态复选框：半选渲染横线而不是对勾。对勾表示「全选」，用它表示「部分」会让用户误读
 * （权限树上会把「部分授予」看成「全部授予」）。上游 shadcn 的 checkbox 不区分这两态，
 * 且 registry 不分发 ui/ 原语（用户装的是上游版本），故本块自带一份。
 * （data-table 的表头全选框刻意只藏对勾、不画横线，因为那里误读的代价小得多，不值得跨块依赖。）*/
export function TriStateCheckbox({
  className,
  ...props
}: React.ComponentProps<typeof CheckboxPrimitive.Root>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn(
        "group peer size-4 shrink-0 rounded-[4px] border border-input shadow-xs transition-shadow outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 data-[state=checked]:border-primary data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground data-[state=indeterminate]:border-primary data-[state=indeterminate]:bg-primary data-[state=indeterminate]:text-primary-foreground dark:bg-input/30 dark:aria-invalid:ring-destructive/40 dark:data-[state=checked]:bg-primary dark:data-[state=indeterminate]:bg-primary",
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="grid place-content-center text-current transition-none"
      >
        <CheckIcon
          data-slot="checkbox-check"
          className="size-3.5 group-data-[state=indeterminate]:hidden"
        />
        <MinusIcon
          data-slot="checkbox-dash"
          className="hidden size-3.5 group-data-[state=indeterminate]:block"
        />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}

import type { ReactNode } from "react";

/**
 * 通用树节点，零业务知识。`label`/`icon` 由消费方传入，本文件不认识任何具体业务字段。
 * `icon` 为函数时按当前展开态求值，用于文件目录式开合图标（folder/folder-open）。
 */
export interface TreeNode {
  id: string;
  label: ReactNode;
  icon?: ReactNode | ((ctx: { expanded: boolean }) => ReactNode);
  children?: TreeNode[];
  disabled?: boolean;
}

/** 收集子树内全部节点 id（含自身），深度优先。 */
export function collectSubtreeIds(node: TreeNode): string[] {
  const ids = [node.id];
  for (const child of node.children ?? []) {
    ids.push(...collectSubtreeIds(child));
  }
  return ids;
}

/** 从根到目标节点的父节点 id 路径（根→父，不含自身）；未找到返回 []。 */
export function findParentChain(nodes: TreeNode[], id: string): string[] {
  return searchParentChain(nodes, id, []) ?? [];
}

function searchParentChain(nodes: TreeNode[], id: string, ancestors: string[]): string[] | null {
  for (const node of nodes) {
    if (node.id === id) {
      return ancestors;
    }
    const found = searchParentChain(node.children ?? [], id, [...ancestors, node.id]);
    if (found !== null) {
      return found;
    }
  }
  return null;
}

/**
 * 推导「子树部分勾选」的父节点集合（自身未勾）。级联策略不在此处，这只是给消费方的只读推导：
 * 子树全勾/全不勾都不算半选；节点自身若已在 `checked` 里，即便子树非全勾也不重复标记。
 */
export function deriveIndeterminate(nodes: TreeNode[], checked: Set<string>): Set<string> {
  const result = new Set<string>();
  walkIndeterminate(nodes, checked, result);
  return result;
}

type SubtreeState = "checked" | "unchecked" | "mixed";

function walkIndeterminate(nodes: TreeNode[], checked: Set<string>, result: Set<string>): void {
  for (const node of nodes) {
    const children = node.children ?? [];
    if (children.length === 0) {
      continue;
    }
    if (subtreeState(node, checked) === "mixed" && !checked.has(node.id)) {
      result.add(node.id);
    }
    walkIndeterminate(children, checked, result);
  }
}

function subtreeState(node: TreeNode, checked: Set<string>): SubtreeState {
  const children = node.children ?? [];
  if (children.length === 0) {
    return checked.has(node.id) ? "checked" : "unchecked";
  }
  const childStates = children.map((child) => subtreeState(child, checked));
  if (childStates.every((state) => state === "checked")) {
    return "checked";
  }
  if (childStates.every((state) => state === "unchecked")) {
    return "unchecked";
  }
  return "mixed";
}

/**
 * 按关键字过滤树：命中节点连同其整棵子树保留（搜到上级还要能逐个勾它的下级），命中节点的祖先链
 * 也保留，其余剔除；`expanded` 是保留下来的父节点 id，交给 `Tree` 的 `defaultExpanded` 才能直接
 * 看到命中的深层节点。`label` 是 ReactNode，只对字符串 label 做匹配——非字符串节点视为不命中，
 * 但其命中的子孙仍会把它保留下来。大小写不敏感；关键字为空白时原样返回，避免无谓重建。
 */
export function filterTree(
  nodes: TreeNode[],
  keyword: string,
): { nodes: TreeNode[]; expanded: string[] } {
  const needle = keyword.trim().toLowerCase();
  if (needle === "") return { nodes, expanded: [] };
  const expanded: string[] = [];
  return { nodes: filterNodes(nodes, needle, expanded), expanded };
}

function filterNodes(nodes: TreeNode[], needle: string, expanded: string[]): TreeNode[] {
  const result: TreeNode[] = [];
  for (const node of nodes) {
    const selfMatches = typeof node.label === "string" && node.label.toLowerCase().includes(needle);
    if (selfMatches) {
      if ((node.children?.length ?? 0) > 0) expanded.push(node.id);
      result.push(node);
      continue;
    }
    const children = filterNodes(node.children ?? [], needle, expanded);
    if (children.length === 0) continue;
    expanded.push(node.id);
    result.push({ ...node, children });
  }
  return result;
}

"use client";

import { useLocalization } from "@jcoder-stack/abp-react/react";
import { ChevronsUpDownIcon } from "lucide-react";
import { type ReactNode, useMemo, useState } from "react";
import { Tree } from "@/components/tree/tree";
import { deriveIndeterminate, filterTree, type TreeNode } from "@/components/tree/tree-helpers";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";

export interface TreeMultiSelectProps {
  nodes: TreeNode[];
  values: string[];
  onChange: (values: string[]) => void;
  placeholder?: string;
  searchPlaceholder?: string;
  emptyText?: string;
  /** 自定义触发按钮上的回显；缺省是「未选→placeholder，≤2 项→名称，>2 项→已选 N 项」。 */
  renderValue?: (count: number, labels: string[]) => ReactNode;
  disabled?: boolean;
  /** 触发按钮的 id，供外部 `<Label htmlFor>` 关联。 */
  id?: string;
  "aria-required"?: boolean;
  "aria-invalid"?: boolean;
}

/** 触发按钮上最多逐个列出的名称条数，再多就只报数量——长名字会把按钮撑出对话框。 */
const MAX_INLINE_LABELS = 2;

function collectLabels(nodes: TreeNode[], values: Set<string>, into: string[]): void {
  for (const node of nodes) {
    if (values.has(node.id) && typeof node.label === "string") into.push(node.label);
    collectLabels(node.children ?? [], values, into);
  }
}

/**
 * 下拉式多选树：可搜索、带三态回显。
 *
 * **不做级联**：勾中父节点不会自动勾中子节点，是否连带下级由调用方决定（比如另给一个「含下级」
 * 开关）——这里替用户勾上子节点会让那个开关失去意义，也会把多余的 id 发给后端。
 */
export function TreeMultiSelect({
  nodes,
  values,
  onChange,
  placeholder,
  searchPlaceholder,
  emptyText,
  renderValue,
  disabled,
  id,
  "aria-required": ariaRequired,
  "aria-invalid": ariaInvalid,
}: TreeMultiSelectProps) {
  const L = useLocalization();
  const [open, setOpen] = useState(false);
  const [keyword, setKeyword] = useState("");

  const checked = useMemo(() => new Set(values), [values]);
  // 半选态按完整树推导：过滤后的树缺了未命中的子节点，据此推导会把「部分勾选」误判成全选。
  const indeterminate = useMemo(() => deriveIndeterminate(nodes, checked), [nodes, checked]);
  const filtered = useMemo(() => filterTree(nodes, keyword), [nodes, keyword]);
  const labels = useMemo(() => {
    const result: string[] = [];
    collectLabels(nodes, checked, result);
    return result;
  }, [nodes, checked]);

  function toggle(id: string, next: boolean) {
    onChange(next ? [...values, id] : values.filter((item) => item !== id));
  }

  function triggerText(): ReactNode {
    if (renderValue) return renderValue(values.length, labels);
    if (values.length === 0) return placeholder ?? L("Tree:SelectPlaceholder");
    // 名称没收齐（有非字符串 label 的节点）就只报数量，否则会少列几项、看着像丢了选择。
    if (labels.length === values.length && values.length <= MAX_INLINE_LABELS) {
      return labels.join(L("Tree:SelectSeparator"));
    }
    return L("Tree:SelectCount", values.length);
  }

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        setOpen(next);
        // 关掉就丢掉搜索词：下次打开要看到完整的树，而不是上一次的过滤结果
        if (!next) setKeyword("");
      }}
    >
      <PopoverTrigger asChild>
        <Button
          id={id}
          type="button"
          variant="outline"
          disabled={disabled}
          aria-required={ariaRequired}
          aria-invalid={ariaInvalid}
          className="w-full justify-between font-normal"
        >
          <span className={values.length === 0 ? "truncate text-muted-foreground" : "truncate"}>
            {triggerText()}
          </span>
          <ChevronsUpDownIcon className="size-4 shrink-0 opacity-50" aria-hidden="true" />
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-(--radix-popover-trigger-width) p-0">
        <div className="border-b p-2">
          <Input
            value={keyword}
            onChange={(event) => setKeyword(event.target.value)}
            placeholder={searchPlaceholder ?? L("Tree:SelectSearch")}
            aria-label={searchPlaceholder ?? L("Tree:SelectSearch")}
          />
        </div>
        <div className="max-h-64 overflow-y-auto p-2">
          {filtered.nodes.length === 0 ? (
            <p className="py-2 text-center text-sm text-muted-foreground">
              {emptyText ?? L("Tree:SelectEmpty")}
            </p>
          ) : (
            // Tree 的展开态是内部 state，只认首次挂载时的 defaultExpanded：关键字变了要重挂载，
            // 否则搜到的深层节点仍藏在收起的父节点里。
            <Tree
              key={keyword}
              nodes={filtered.nodes}
              defaultExpanded={filtered.expanded}
              checkable
              checked={checked}
              indeterminate={indeterminate}
              onCheckChange={toggle}
            />
          )}
        </div>
        <div className="flex items-center justify-between border-t px-3 py-2">
          <span className="text-xs text-muted-foreground">
            {L("Tree:SelectCount", values.length)}
          </span>
          {values.length > 0 ? (
            <Button type="button" variant="ghost" size="sm" onClick={() => onChange([])}>
              {L("Tree:SelectClear")}
            </Button>
          ) : null}
        </div>
      </PopoverContent>
    </Popover>
  );
}

{
  "en": {
    "": {
      "Tree:Expand": "Expand",
      "Tree:Collapse": "Collapse",
      "Tree:SelectPlaceholder": "Select",
      "Tree:SelectSearch": "Search",
      "Tree:SelectEmpty": "No matches",
      "Tree:SelectCount": "{0} selected",
      "Tree:SelectClear": "Clear",
      "Tree:SelectSeparator": ", "
    }
  },
  "zh-Hans": {
    "": {
      "Tree:Expand": "展开",
      "Tree:Collapse": "收起",
      "Tree:SelectPlaceholder": "选择",
      "Tree:SelectSearch": "搜索",
      "Tree:SelectEmpty": "无匹配项",
      "Tree:SelectCount": "已选 {0} 项",
      "Tree:SelectClear": "清空",
      "Tree:SelectSeparator": "、"
    }
  }
}
